# Audits of supplied operational retail panels and targets.
.vr_rows<-function(value,name){if(inherits(value,'CalcResult'))value<-value$value;if(!is.list(value)||!is.null(names(value))||any(!vapply(value,.cr_object,logical(1)))).cr_error('RETAIL_VALIDATION_SCHEMA',paste(name,'must be record array'));value}
validate_retail_cohort<-function(application_targets,account_panel,behavioral_targets,target_profile,split_memberships,source_lineage,design,context=NULL){
 d<-.vb_design(design,context);apps<-.vr_rows(application_targets,'application_targets');panel<-if(inherits(account_panel,'CalcResult'))account_panel$value else account_panel;if(.cr_object(panel))panel<-panel$accounts;panel<-.vr_rows(panel,'account_panel');targets<-.vr_rows(behavioral_targets,'behavioral_targets');splits<-.vr_rows(split_memberships,'split_memberships');sources<-.vr_rows(source_lineage,'source_lineage');profile<-.ex_object(target_profile,'target_profile');for(key in c('profile_id','version','reference','default_definition','default_group_rule')).vb_string(profile[[key]],key);if(!(profile$default_unit%in%c('facility','obligor'))||!is.logical(profile$first_default)||length(profile$first_default)!=1||is.na(profile$first_default)||!(profile$exit_treatment%in%c('competing','censor'))).cr_error('RETAIL_VALIDATION_PROFILE','Explicit default unit, first-default and exit conventions required');.ex_ids(lapply(c('default_event','chargeoff_event','cure_event'),function(k)profile[[k]]),'distinct event concepts');rules<-.ex_object(profile$risk_set_by_product,'risk_set_by_product');isolation<-.ex_ids(profile$split_isolation_keys,'split_isolation_keys');ah<-.vb_number(profile$application_horizon_days,'application_horizon_days',1);bh<-.vb_number(profile$behavioral_horizon_months,'behavioral_horizon_months',1);if(ah!=floor(ah)||bh!=floor(bh)).cr_error('RETAIL_VALIDATION_PROFILE','Integer target horizons required');for(product in names(rules)){rule<-rules[[product]];.vb_string(product,'product_id');.ex_ids(rule$active_states,'active_states');if(!is.logical(rule$include_zero_balance)||length(rule$include_zero_balance)!=1||is.na(rule$include_zero_balance)).cr_error('RETAIL_VALIDATION_PROFILE','Explicit product-qualified zero-balance rule required')}
 profile_known<-.cr_data_date(profile$known_at,'profile known_at');cutoff<-.cr_data_date(d$evaluation_cutoff,'evaluation_cutoff');violations<-list();coverage<-flow<-list();seen<-character();account_keys<-prediction_dates<-list();units<-character();keyfor<-function(a,b)paste0(a,'@',b);issue<-function(code,unit,detail){violations[[length(violations)+1]]<<-list(code=code,unit_id=unit,detail=detail)};increment<-function(x,key,amount=1){x[[key]]<-if(is.null(x[[key]]))as.numeric(amount)else x[[key]]+amount;x};isbool<-function(x)is.logical(x)&&length(x)==1&&!is.na(x)
 for(row in apps){app<-.vb_string(row$application_id,'application_id');customer<-.vb_string(row$customer_id,'customer_id');units<-unique(c(units,customer));if(app%in%seen)issue('DUPLICATE_APPLICATION',app,'Application target appears more than once');seen<-c(seen,app);asof<-.cr_data_date(row$information_cutoff,'information_cutoff');prediction_dates[[paste0('application:',app)]]<-asof;if(asof>cutoff)issue('FUTURE_APPLICATION',app,'Prediction cutoff exceeds validation cutoff');for(flag in c('approved','accepted','booked','funded','mature','eligible','label_observed'))if(!isbool(row[[flag]])).cr_error('RETAIL_VALIDATION_SCHEMA',paste('Application Boolean',flag,'required'));flow<-increment(flow,'applications');for(flag in c('approved','accepted','booked','funded'))flow<-increment(flow,flag,row[[flag]]);if((row$accepted&&!row$approved)||(row$booked&&!row$accepted)||(row$funded&&!row$booked))issue('SELECTION_FLOW_CONFLICT',app,'Funding must follow booking, acceptance and approval');flow<-increment(flow,'accepted_not_funded',row$accepted&&!row$funded);label<-row$target;if(!is.null(label)&&(!is.numeric(label)||length(label)!=1||!label%in%c(0,1))).cr_error('RETAIL_VALIDATION_SCHEMA','Application target must be binary or null');if(row$label_observed!=!is.null(label))issue('LABEL_OBSERVABILITY_CONFLICT',app,'Label flag differs from actual label');if(!row$funded){if(!is.null(label)||row$eligible)issue('UNFUNDED_OWN_CONTRACT_OUTCOME',app,'Never-funded own contract has no observed outcome')}else{.vb_string(row$facility_id,'facility_id');start<-.cr_data_date(row$performance_start,'performance_start');end<-.cr_data_date(row$outcome_end,'outcome_end');if(start<asof||as.numeric(end-start)!=ah)issue('APPLICATION_WINDOW_CONFLICT',app,'Performance must follow prediction with declared horizon');if(row$mature!=(end<=cutoff))issue('MATURITY_FLAG_CONFLICT',app,'Calendar maturity differs from declared cutoff');coverage<-increment(coverage,'application_mature_observed',end<=cutoff&&!is.null(label)&&row$eligible);coverage<-increment(coverage,'application_early_known_event',isTRUE(label==1)&&end>cutoff);if(isTRUE(label==0)&&(end>cutoff||is.null(row$observed_until)||.cr_data_date(row$observed_until,'observed_until')<end))issue('UNSUPPORTED_APPLICATION_NONDEFAULT',app,'Negative own-contract outcome requires mature complete follow-up');if(isTRUE(label==1)&&is.null(row$event_id))issue('MISSING_DEFAULT_EVENT_PROVENANCE',app,'Positive label lacks default event ID')};if(!is.null(label)&&!is.null(row$label_origin)&&row$label_origin%in%c('NO_HIT','THIN_FILE','PSEUDO','HYPOTHETICAL'))issue('NON_OUTCOME_LABEL_SOURCE',app,'Missing bureau evidence or pseudolabel is not a factual outcome');if(profile$default_unit=='obligor'&&is.null(row$default_group_id))issue('MISSING_DEFAULT_GROUP',app,'Obligor target requires an explicit default-group assignment')}
 for(row in panel){account<-.vb_string(row$account_id,'account_id');customer<-.vb_string(row$customer_id,'customer_id');units<-unique(c(units,customer));asof<-.cr_data_date(row$as_of,'as_of');known<-.cr_data_date(row$known_at,'known_at');opened<-.cr_data_date(row$opened_at,'opened_at');unit<-keyfor(account,row$as_of);key<-unit;if(!is.null(account_keys[[key]]))issue('DUPLICATE_ACCOUNT_MONTH',unit,'Account-month snapshot repeated');account_keys[[key]]<-row;prediction_dates[[paste0('account:',unit)]]<-known;if(known>asof||asof>cutoff||opened>asof)issue('ACCOUNT_DATE_CONFLICT',unit,'Snapshot knowledge/opening/as-of chronology invalid');mob<-(as.integer(format(asof,'%Y'))-as.integer(format(opened,'%Y')))*12+as.integer(format(asof,'%m'))-as.integer(format(opened,'%m'));if(row$months_on_book!=mob||format(asof+1,'%d')!='01')issue('ACCOUNT_MOB_CONFLICT',unit,'Calendar month-end/MOB differs from origin');if(!isbool(row$at_risk)||!isbool(row$ever_default)).cr_error('RETAIL_VALIDATION_SCHEMA','Account risk/default flags required');rule<-rules[[row$product_id]];balance<-row$features$balance;if(is.null(rule))issue('UNDECLARED_PRODUCT_RISK_SET',unit,'No product risk-set rule')else{expected<-row$lifecycle_state%in%unlist(rule$active_states)&&!(profile$first_default&&row$ever_default)&&(rule$include_zero_balance||is.null(balance)||balance!=0);if(row$at_risk!=expected)issue('RISK_SET_CONFLICT',unit,'Risk membership differs from declared product/default profile');if(isTRUE(balance==0)&&expected)coverage<-increment(coverage,'active_zero_balance_at_risk')};coverage<-increment(coverage,'account_months');coverage<-increment(coverage,'account_months_at_risk',row$at_risk);coverage<-increment(coverage,'incomplete_feature_snapshots',!isTRUE(row$source_complete))}
 seen_targets<-character();for(row in targets){account<-.vb_string(row$account_id,'target account_id');asof<-.cr_data_date(row$as_of,'target as_of');end<-.cr_data_date(row$horizon_end,'horizon_end');key<-keyfor(account,row$as_of);unit<-key;origin<-account_keys[[key]];if(key%in%seen_targets)issue('DUPLICATE_BEHAVIORAL_TARGET',unit,'Repeated account target');seen_targets<-c(seen_targets,key);if(is.null(origin))issue('TARGET_WITHOUT_SNAPSHOT',unit,'Target has no matching account snapshot')else if(!identical(row$customer_id,origin$customer_id))issue('TARGET_CUSTOMER_CONFLICT',unit,'Target customer differs from snapshot');if(end!=.cr_beh_month(asof,bh)||!identical(row$target_event,profile$default_event)||!identical(row$evaluation_cutoff,d$evaluation_cutoff))issue('BEHAVIORAL_TARGET_CONFLICT',unit,'Target horizon/event/cutoff differs from profile');label<-row$label;mature<-end<=cutoff;if(!is.null(label)&&(!is.numeric(label)||length(label)!=1||!label%in%c(0,1))).cr_error('RETAIL_VALIDATION_SCHEMA','Behavioral label must be binary/null');if(!identical(row$calendar_mature,mature)||!identical(row$outcome_complete,!is.null(label)))issue('BEHAVIORAL_MATURITY_CONFLICT',unit,'Maturity/completeness flag conflicts with dates or label');if(isTRUE(label==0)){if(identical(row$status,'COMPETING_EVENT')){if(profile$exit_treatment!='competing'||!row$first_event_type%in%unlist(profile$competing_events))issue('COMPETING_TARGET_CONFLICT',unit,'Exit zero requires declared competing-risk estimand')}else if(!mature||is.null(row$followup_days)||row$followup_days<as.numeric(end-asof))issue('UNSUPPORTED_BEHAVIORAL_NONDEFAULT',unit,'Negative label lacks mature complete follow-up')};if(isTRUE(label==1)&&(!identical(row$first_event_type,profile$default_event)||is.null(row$first_event_id)))issue('BEHAVIORAL_EVENT_PROVENANCE',unit,'Default label lacks matching default event provenance');if(isTRUE(row$eligible)&&!is.null(origin)&&!origin$at_risk)issue('TARGET_OUTSIDE_RISK_SET',unit,'Eligible target contradicts snapshot risk set');coverage<-increment(coverage,'behavioral_mature_observed',mature&&!is.null(label)&&isTRUE(row$eligible));coverage<-increment(coverage,'behavioral_early_known_event',isTRUE(label==1)&&!mature);coverage<-increment(coverage,'behavioral_missing_outcomes',is.null(label))}
 for(key in names(account_keys))if(!key%in%seen_targets)issue('SNAPSHOT_WITHOUT_TARGET',key,'Account snapshot has no target audit record');group_roles<-list();group_labels<-list();split_units<-character();for(row in splits){customer<-.vb_string(row$customer_id,'split customer_id');role<-.vb_string(row$role,'split role');split_units<-unique(c(split_units,customer));if(!customer%in%units)issue('UNKNOWN_SPLIT_CUSTOMER',customer,'Split assignment has no application/account');for(key in isolation){group<-row[[key]];if(!is.character(group)||length(group)!=1||!nzchar(group)){issue('MISSING_SPLIT_GROUP',customer,paste0(key,' unavailable'));next};id<-.cr_hash(list(key,group));group_roles[[id]]<-unique(c(group_roles[[id]],role));group_labels[[id]]<-c(key,group)}};if(length(group_roles)){orderkeys<-order(vapply(group_labels,function(g)g[1],character(1)),vapply(group_labels,function(g)g[2],character(1)));for(id in names(group_roles)[orderkeys])if(length(group_roles[[id]])>1)issue('SPLIT_GROUP_OVERLAP',group_labels[[id]][2],paste0(group_labels[[id]][1],' crosses ',paste(sort(group_roles[[id]]),collapse=',')))};for(customer in sort(setdiff(units,split_units)))issue('MISSING_SPLIT_ASSIGNMENT',customer,'No declared split-group isolation evidence')
 for(row in sources){source<-.vb_string(row$source_id,'source_id');key<-.vb_string(row$prediction_key,'prediction_key');available<-.cr_data_date(row$available_at,'available_at');observed<-.cr_data_date(row$observed_at,'observed_at');.vb_string(row$source_hash,'source_hash');kind<-.vb_string(row$kind,'source kind');if(is.null(prediction_dates[[key]]))issue('UNKNOWN_SOURCE_PREDICTION',source,'Lineage points to unknown snapshot')else if(available>prediction_dates[[key]]||observed>prediction_dates[[key]])issue('FEATURE_LOOKAHEAD',source,'Feature evidence was unavailable at original prediction cutoff');if(kind%in%c('TARGET','OUTCOME','POST_DECISION'))issue('OUTCOME_IN_FEATURE_PATH',source,'Future target/decision evidence cannot be a historical feature')};for(key in sort(names(prediction_dates)))if(profile_known>prediction_dates[[key]])issue('PROFILE_LOOKAHEAD',key,'Target/risk profile was unavailable at original prediction cutoff');seen_source_keys<-vapply(sources,function(r)r$prediction_key,character(1));for(key in sort(setdiff(names(prediction_dates),seen_source_keys)))issue('MISSING_FEATURE_LINEAGE',key,'No source evidence for frozen snapshot');counts<-list();for(v in violations)counts<-increment(counts,v$code);ordered<-function(x){if(!length(x))return(structure(list(),names=character()));x[sort(names(x))]};value<-list(artifact_type='ValidationResult',design=d,target_profile=profile,metrics=list(population_flow=ordered(flow),maturity_and_risk_coverage=ordered(coverage)),violations=violations,violation_counts=ordered(counts),decision=list(status=if(length(violations))'FAIL'else'PASS',scope='DECLARED_RETAIL_COHORT_CONTRACT'),applicability=if(length(apps)||length(panel))'APPLICABLE'else'NOT_APPLICABLE',reason=if(length(apps)||length(panel))NULL else'EMPTY_RETAIL_POPULATION',empirical_performance_assessed=FALSE,source_provenance_authenticated=FALSE,input_fingerprint=.cr_hash(list(application_targets=apps,account_panel=panel,behavioral_targets=targets,split_memberships=splits,source_lineage=sources)));if(!length(apps)&&!length(panel))value$decision$status<-'NOT_APPLICABLE';.cr_result(value,'validation.validate_retail_cohort','cohort_audit',context,limitations='Audits supplied operational tables without constructing substitute targets. Early defaults remain visible but not mature performance. Household links control dependence, not default contagion. Provenance is declared, not authenticated.')
}

roll_rate_backtest<-function(forecasts,account_panel,states,state_contract,design,weighting,uncertainty,cluster_resamples=NULL,confidence_level=.95,context=NULL){
 d<-.vb_design(design,context);rows<-.vb_records(forecasts,d);panel<-.vr_rows(account_panel,'account_panel');levels<-.ex_ids(states,'states');contract<-.ex_object(state_contract,'state_contract');if(d$target$time_unit!='months'||floor(d$target$horizon)!=d$target$horizon).cr_error('ROLL_RATE_HORIZON','Whole-calendar-month transition horizon required');if(!weighting%in%c('count','opening_balance')).cr_error('ROLL_RATE_WEIGHT','Use count or opening_balance');defaults<-.ex_ids(contract$default_states,'default_states');cures<-.ex_ids(contract$cure_states,'cure_states',empty=TRUE);absorbing<-.ex_ids(contract$absorbing_states,'absorbing_states',empty=TRUE);chargeoffs<-.ex_ids(contract$chargeoff_states,'chargeoff_states',empty=TRUE);if(!all(chargeoffs%in%defaults)).cr_error('ROLL_RATE_STATES','Charge-off must be separately identified subset of default states');index<-list();seen<-character()
 for(row in panel){account<-.vb_string(row$account_id,'account_id');at<-.cr_data_date(row$as_of,'as_of');known<-.cr_data_date(row$known_at,'known_at');.vb_string(row$risk_episode_id,'risk_episode_id');if(known<at||!row$state%in%levels).cr_error('ROLL_RATE_PANEL','State knowledge must follow observation and state be declared');if(row$state%in%defaults).vb_string(row$default_episode_id,'default_episode_id');key<-.cr_hash(list(account,row$as_of,row$known_at));if(key%in%seen).cr_error('ROLL_RATE_AMBIGUITY','Duplicate equally dated observation');seen<-c(seen,key);index[[account]]<-c(index[[account]],list(row))}
 converted<-matrices<-traces<-episode_violations<-list();weights<-numeric();origins<-list();missing<-0
 for(row in rows){account<-.vb_string(row$account_id,'forecast account_id');.vb_string(row$risk_episode_id,'forecast risk_episode_id');history<-index[[account]];available<-Filter(function(r)r$as_of==row$as_of&&r$known_at<=row$forecast_known_at,history);if(!length(available)).cr_error('ROLL_RATE_ORIGIN','Exact historically known origin required');origin<-available[[which.max(as.numeric(as.Date(vapply(available,function(r)r$known_at,character(1)))))]];if(!identical(origin$state,row$origin_state)||!identical(origin$risk_episode_id,row$risk_episode_id)||!identical(origin$default_episode_id,row$default_episode_id)).cr_error('ROLL_RATE_ORIGIN','Origin state/episodes differ from historical snapshot');origins[[row$origin_state]]<-if(is.null(origins[[row$origin_state]]))1 else origins[[row$origin_state]]+1;future<-Filter(function(r)r$as_of>row$as_of&&r$as_of<=row$horizon_end&&r$known_at<=d$evaluation_cutoff,history);latest<-list();for(r in future)if(is.null(latest[[r$as_of]])||r$known_at>latest[[r$as_of]]$known_at)latest[[r$as_of]]<-r;trajectory<-c(list(origin),unname(latest[sort(names(latest))]));endpoint<-latest[[row$horizon_end]];if(is.null(endpoint)){old<-Filter(function(r)r$state%in%absorbing,trajectory);if(length(old))endpoint<-old[[length(old)]]};converted_row<-row;converted_row$transition_matrix<-.ex_rows(.ex_matrix(row$transition_matrix,'transition matrix'));converted_row$scale_id<-contract$scale_id;converted_row$scale_version<-contract$scale_version;converted_row$observation_status<-if(is.null(endpoint))'CENSORED'else'OBSERVED';converted_row['destination_state']<-list(if(is.null(endpoint))NULL else endpoint$state);converted_row['state_observed_at']<-list(if(is.null(endpoint))NULL else endpoint$as_of);converted_row$outcome_known_at<-if(is.null(endpoint))d$evaluation_cutoff else endpoint$known_at;if(is.null(endpoint))missing<-missing+1;seen_episodes<-character();last_default<-NULL;cure_count<-redefault_count<-0;if(origin$state%in%defaults){last_default<-origin$default_episode_id;seen_episodes<-c(seen_episodes,last_default)};local<-character()
 if(length(trajectory)>1)for(i in seq_len(length(trajectory)-1)){previous<-trajectory[[i]];current<-trajectory[[i+1]];if(previous$state%in%absorbing&&current$state!=previous$state)local<-c(local,'ABSORBING_STATE_DEPARTURE');if(current$state%in%cures&&previous$state%in%defaults){cure_count<-cure_count+1;if(current$risk_episode_id==previous$risk_episode_id)local<-c(local,'CURE_WITHOUT_NEW_RISK_EPISODE')};if(current$state%in%defaults){ep<-current$default_episode_id;if(previous$state%in%defaults&&ep!=previous$default_episode_id)local<-c(local,'DEFAULT_EPISODE_CHANGED_WITHOUT_CURE')else if(!previous$state%in%defaults){if(ep%in%seen_episodes)local<-c(local,'REUSED_DEFAULT_EPISODE_AFTER_CURE');if(!is.null(last_default))redefault_count<-redefault_count+1};seen_episodes<-unique(c(seen_episodes,ep));last_default<-ep}}
 if(length(local)){episode_violations[[length(episode_violations)+1]]<-list(prediction_id=row$prediction_id,codes=as.list(sort(unique(local))));converted_row$observation_status<-'CENSORED'};traces[[length(traces)+1]]<-list(prediction_id=row$prediction_id,account_id=account,origin_state=row$origin_state,horizon_end=row$horizon_end,selected_endpoint_at=if(is.null(endpoint))NULL else endpoint$as_of,selected_endpoint_known_at=if(is.null(endpoint))NULL else endpoint$known_at,missing_exact_successor=is.null(latest[[row$horizon_end]]),cure_transitions=cure_count,redefault_transitions=redefault_count,episode_violation_codes=as.list(sort(unique(local))),risk_episode_ids=lapply(trajectory,function(r)r$risk_episode_id),default_episode_ids=lapply(trajectory,function(r)r$default_episode_id));matrices[[length(matrices)+1]]<-row$transition_matrix;converted[[length(converted)+1]]<-converted_row;weights<-c(weights,if(weighting=='count')1 else .vb_number(row$opening_balance,'opening_balance',0))}
 if(!length(rows)).cr_error('ROLL_RATE_FORECASTS','At least one frozen transition forecast required');checked<-rating_migration_backtest(converted,matrices,states=levels,state_contract=contract,design=d,uncertainty=uncertainty,weights=weights,cluster_resamples=cluster_resamples,confidence_level=confidence_level,context=context)$value;extra<-list(account_panel_fingerprint=.cr_hash(panel),endpoint_traces=traces,episode_violations=episode_violations,origin_account_counts=origins[sort(names(origins))],missing_successor_count=missing,weighting=weighting,zero_balance_origin_count=sum(vapply(rows,function(r)isTRUE(r$opening_balance==0),logical(1))),observed_chargeoff_destinations=sum(vapply(converted,function(r)!is.null(r$destination_state)&&r$destination_state%in%chargeoffs&&r$observation_status=='OBSERVED',logical(1))),no_missing_month_compression=TRUE);checked$diagnostics<-c(checked$diagnostics,extra);.cr_result(checked,'validation.roll_rate_backtest','retail_transition_validation',context,limitations='Reuses migration scores with exact horizon endpoints except declared absorption. Missing months do not imply self-transitions. Episode IDs are supplied provenance, not hidden-event inference; calibration is conditional on observed valid successors.')
}
